import React, { useState, useEffect } from 'react';
import './App.css';
import { authService } from './authService';

function App() {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [apiData, setApiData] = useState(null);

  useEffect(() => {
    checkAuth();
  }, []);

  const checkAuth = async () => {
    setLoading(true);
    const userData = await authService.getUser();
    setUser(userData);
    setLoading(false);
  };

  const handleLogin = () => {
    authService.login();
  };

  const handleLogout = () => {
    authService.logout();
  };

  const fetchData = async () => {
    try {
      const data = await authService.getData();
      setApiData(data);
    } catch (error) {
      alert('Failed to fetch data. Please login first.');
    }
  };

  if (loading) {
    return <div className="App">Loading...</div>;
  }

  return (
    <div className="App">
      <header className="App-header">
        <h1>React BFF Demo</h1>

        {user && user.isAuthenticated ? (
          <div>
            <p>Welcome, <strong>{user.username}</strong>!</p>
            <button onClick={handleLogout} style={buttonStyle}>Logout</button>
            <button onClick={fetchData} style={buttonStyle}>Fetch API Data</button>

            {apiData && (
              <div style={dataBoxStyle}>
                <h3>API Response:</h3>
                <pre>{JSON.stringify(apiData, null, 2)}</pre>
              </div>
            )}

            <div style={claimsBoxStyle}>
              <h3>User Claims:</h3>
              <pre>{JSON.stringify(user.claims, null, 2)}</pre>
            </div>
          </div>
        ) : (
          <div>
            <p>You are not logged in.</p>
            <button onClick={handleLogin} style={buttonStyle}>Login</button>
          </div>
        )}
      </header>
    </div>
  );
}

const buttonStyle = {
  margin: '10px',
  padding: '10px 20px',
  fontSize: '16px',
  cursor: 'pointer',
  backgroundColor: '#61dafb',
  border: 'none',
  borderRadius: '5px',
  color: '#282c34'
};

const dataBoxStyle = {
  marginTop: '20px',
  padding: '20px',
  backgroundColor: '#1e1e1e',
  borderRadius: '5px',
  textAlign: 'left'
};

const claimsBoxStyle = {
  marginTop: '20px',
  padding: '20px',
  backgroundColor: '#1e1e1e',
  borderRadius: '5px',
  maxWidth: '600px',
  textAlign: 'left'
};

export default App;
